import React, { useState, useEffect } from 'react';
import { getUsers, deleteUser, updateUser } from '../services/api'; // Import necessary API functions

const UserManagement = () => {
  const [users, setUsers] = useState([]); // State to store the list of users
  const [loading, setLoading] = useState(true); // State for loading indication
  const [error, setError] = useState(null); // State to handle errors

  // Fetch users when the component mounts
  useEffect(() => {
    const fetchUsers = async () => {
      setLoading(true);
      try {
        const response = await getUsers(); // Fetch users
        console.log("Fetched Users:", response.data); // Log the response
  
        // Make sure response.data is an array before setting the state
        if (Array.isArray(response.data)) {
          setUsers(response.data); // Set the users state if data is valid
        } else {
          setError('Invalid user data format.');
        }
        setError(null); // Clear any previous errors
      } catch (error) {
        console.error('Error fetching users:', error);
        setError('Error fetching users. Please try again later.');
      } finally {
        setLoading(false); // Set loading to false once the request is complete
      }
    };
  
    fetchUsers();
  }, []); // Empty dependency array to run only once when the component mounts
  // Empty dependency array to run once when the component mounts

  // Handle delete user
  const handleDelete = async (userId) => {
    try {
      await deleteUser(userId); // Assuming deleteUser sends DELETE request to delete a user
      setUsers(users.filter(user => user._id !== userId)); // Remove user from state after deletion
    } catch (error) {
      setError('Error deleting user. Please try again later.');
    }
  };

  // Handle update user (example: change role or any user info)
  const handleUpdate = async (userId, updatedData) => {
    try {
      const updatedUser = await updateUser(userId, updatedData); // Assuming updateUser sends PUT request
      setUsers(users.map(user => user._id === userId ? updatedUser.data : user)); // Update the user in the state
    } catch (error) {
      setError('Error updating user. Please try again later.');
    }
  };

  return (
    <div>
      <h1>User Management</h1>
      {loading && <p>Loading users...</p>}
      {error && <p style={{ color: 'red' }}>{error}</p>}

      {users?.length > 0 ? (
        <table>
          <thead>
            <tr>
              <th>Username</th>
              <th>Role</th>
              <th>Franchise</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {users.map((user) => (
              <tr key={user._id}>
                <td>{user.username}</td>
                <td>{user.role}</td>
                <td>{user.franchise ? user.franchise.name : 'N/A'}</td>
                <td>
                  <button onClick={() => handleUpdate(user._id, { role: 'admin' })}>Make Admin</button>
                  <button onClick={() => handleDelete(user._id)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No users found.</p>
      )}
    </div>
  );
};

export default UserManagement;
